-- 02_patients.sql
-- 25 synthetic patients: SYN-001 to SYN-025, ages 30 to 84.
-- No real names or identifiers. Run once in SQL Workshop > SQL Scripts.
-- One INSERT ... SELECT statement: patient_id is generated by Oracle.

insert into patients (patient_reference, age_years)
select 'SYN-' || lpad(level, 3, '0'),
       30 + mod(level * 7, 55)
  from dual
connect by level <= 25;

commit;

select patient_id, patient_reference, age_years
  from patients
 order by patient_reference;
